def compute(vars):
    cost_of_repurchased_shares = vars["Cost of Repurchased Shares"]
    treasury_stock = cost_of_repurchased_shares
    return {
        "value": treasury_stock,
        "trace": {
            "Cost of Repurchased Shares": cost_of_repurchased_shares,
            "Treasury Stock": treasury_stock,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
